        Colors[0] := 'C80000'; // Red
        Colors[1] := '0000C8'; // Blue
        Colors[2] := '009600'; // Green
        Colors[3] := '800080'; // Purple
        Colors[4] := 'FF6000'; // Orange
        Colors[5] := 'FFFF00'; // Yellow
        Colors[6] := 'FFFFFF'; // White

        R := 0.65;

        H := R * sin(Pi / 5);
        sAngle := Pi * 2 / 5;
        for i := 0 to 4 do begin
            x[i] := R * sin(sAngle * i);
            y[i] := R * cos(sAngle * i);
        end;

        D1 := R * (sqrt(5) + 3) / 12;
        D2 := H / 3;
